create extension if not exists pgcrypto;
create table if not exists public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, role text not null check (role in ('admin','editor')), unique(user_id,role));
create or replace function public.has_site_role(required_role text) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and role=required_role); $$;
create table if not exists public.site_settings (id uuid primary key default gen_random_uuid(), key text unique not null, value jsonb not null default '{}', updated_at timestamptz default now());
create table if not exists public.sections (id uuid primary key default gen_random_uuid(), slug text unique not null, title text not null, content jsonb not null default '{}', is_visible boolean not null default true, sort_order int not null default 0, updated_at timestamptz default now());
create table if not exists public.projects (id uuid primary key default gen_random_uuid(), slug text unique not null, title text not null, summary text, body text, category text, tags text[] default '{}', role text, tools text[] default '{}', cover_url text, live_url text, source_url text, featured boolean default false, published boolean default false, sort_order int default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.project_media (id uuid primary key default gen_random_uuid(), project_id uuid references public.projects(id) on delete cascade, url text not null, alt_text text default '', sort_order int default 0);
create table if not exists public.skills (id uuid primary key default gen_random_uuid(), name text not null, group_name text, description text, sort_order int default 0, published boolean default true);
create table if not exists public.experiences (id uuid primary key default gen_random_uuid(), company text, role text not null, description text, start_date date, end_date date, current_role boolean default false, sort_order int default 0, published boolean default true);
create table if not exists public.education (id uuid primary key default gen_random_uuid(), institution text not null, qualification text, description text, start_date date, end_date date, sort_order int default 0, published boolean default true);
create table if not exists public.services (id uuid primary key default gen_random_uuid(), title text not null, description text, icon text, sort_order int default 0, published boolean default true);
create table if not exists public.testimonials (id uuid primary key default gen_random_uuid(), person text not null, role text, quote text not null, avatar_url text, sort_order int default 0, published boolean default true);
create table if not exists public.categories (id uuid primary key default gen_random_uuid(), name text unique not null, slug text unique not null, kind text not null default 'article');
create table if not exists public.articles (id uuid primary key default gen_random_uuid(), slug text unique not null, title text not null, excerpt text, body text, cover_url text, category_id uuid references public.categories(id) on delete set null, tags text[] default '{}', status text not null default 'draft' check(status in ('draft','published')), published_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.social_links (id uuid primary key default gen_random_uuid(), platform text not null, url text not null, label text, sort_order int default 0, is_visible boolean default true);
create table if not exists public.videos (id uuid primary key default gen_random_uuid(), title text not null, youtube_url text not null, description text, sort_order int default 0, is_visible boolean default true);
create table if not exists public.navigation_items (id uuid primary key default gen_random_uuid(), label text not null, href text not null, sort_order int default 0, is_visible boolean default true);
create table if not exists public.contact_messages (id uuid primary key default gen_random_uuid(), name text not null, email text not null, subject text, message text not null, status text not null default 'unread' check(status in ('unread','read','archived')), created_at timestamptz default now());
create table if not exists public.media_assets (id uuid primary key default gen_random_uuid(), storage_path text not null, public_url text, filename text not null, mime_type text, size_bytes bigint, alt_text text default '', created_at timestamptz default now());
create table if not exists public.admin_audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, entity text, entity_id uuid, details jsonb default '{}', created_at timestamptz default now());
-- RLS: public reads only published/visible content. Writes require the admin role.
do $$ declare t text; begin foreach t in array array['site_settings','sections','projects','project_media','skills','experiences','education','services','testimonials','categories','articles','social_links','videos','navigation_items','contact_messages','media_assets','admin_audit_logs','user_roles'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy "public read visible sections" on public.sections for select using (is_visible or public.has_site_role('admin'));
create policy "admin manage sections" on public.sections for all using (public.has_site_role('admin')) with check (public.has_site_role('admin'));
create policy "public read published projects" on public.projects for select using (published or public.has_site_role('admin'));
create policy "admin manage projects" on public.projects for all using (public.has_site_role('admin')) with check (public.has_site_role('admin'));
create policy "public read published articles" on public.articles for select using (status='published' or public.has_site_role('admin'));
create policy "admin manage articles" on public.articles for all using (public.has_site_role('admin')) with check (public.has_site_role('admin'));
create policy "public insert contact messages" on public.contact_messages for insert with check (true);
create policy "admin read and manage messages" on public.contact_messages for all using (public.has_site_role('admin')) with check (public.has_site_role('admin'));
-- Remaining CMS tables: public select only for published/visible rows; admin full access.
do $$ declare t text; begin foreach t in array array['site_settings','project_media','skills','experiences','education','services','testimonials','categories','social_links','videos','navigation_items','media_assets','admin_audit_logs','user_roles'] loop execute format('create policy "admin manage %1$s" on public.%1$I for all using (public.has_site_role('admin')) with check (public.has_site_role('admin'))',t); end loop; end $$;
create policy "public read visible skills" on public.skills for select using (published or public.has_site_role('admin'));
create policy "public read visible experiences" on public.experiences for select using (published or public.has_site_role('admin'));
create policy "public read visible education" on public.education for select using (published or public.has_site_role('admin'));
create policy "public read visible services" on public.services for select using (published or public.has_site_role('admin'));
create policy "public read visible testimonials" on public.testimonials for select using (published or public.has_site_role('admin'));
create policy "public read visible socials" on public.social_links for select using (is_visible or public.has_site_role('admin'));
create policy "public read visible videos" on public.videos for select using (is_visible or public.has_site_role('admin'));
create policy "public read visible navigation" on public.navigation_items for select using (is_visible or public.has_site_role('admin'));
create policy "public read categories" on public.categories for select using (true);
create policy "public read project media" on public.project_media for select using (exists(select 1 from public.projects p where p.id=project_id and p.published) or public.has_site_role('admin'));